statement:
Write `checkIfInstanceOf(obj, classFunction)`, which returns `true` when the value `obj` is an instance of the class `classFunction` or of any class that extends it, and `false` otherwise.

Here a value counts as an instance of a class when it can use that class's methods, that is, when `classFunction.prototype` lies somewhere on the prototype chain of `obj`. Primitives count too: `5` is an instance of `Number`, since it can call `toFixed`, even though `5 instanceof Number` is `false`. Both arguments may be any value at all, including `undefined`, `null` and values that are not functions; the function must never throw.

A case cannot hold real objects or classes, so each case gives `obj` and `classFunction` as short JavaScript expressions, and the judge evaluates them before calling your function. An expression is one of:

- a JSON value (`5`, `-2.5`, `"hello"`, `true`, `null`, `[1, 2]`, `{"a": 1}`), or `undefined`;
- a BigInt such as `7n`, `Symbol()`, `Object.create(null)` (an object with no prototype at all), or the arrow function `() => {}`;
- a class name: `Date`, `Number`, `String`, `Boolean`, `Object`, `Array`, `Function`, `Map`, `Set`, `Error`, `TypeError`, `BigInt`, `Symbol`, or one of `Animal`, `Dog` and `Cat`, which are defined as `class Animal {}`, `class Dog extends Animal {}` and `class Cat extends Animal {}`;
- `new` and one of those class names other than `Function`, `BigInt` and `Symbol`, with no arguments, such as `new Dog()`.

validator:
function validate(input) {
  const names = ['Date', 'Number', 'String', 'Boolean', 'Object', 'Array', 'Function', 'Map', 'Set', 'Error', 'TypeError', 'BigInt', 'Symbol', 'Animal', 'Dog', 'Cat'];
  const fixed = ['undefined', 'Symbol()', 'Object.create(null)', '() => {}'];
  for (const text of input) {
    if (typeof text !== 'string' || text.length === 0 || text.length > 200) return 'Each argument is an expression of 1 to 200 characters.';
    if (fixed.includes(text) || names.includes(text) || /^-?\d{1,15}n$/.test(text)) continue;
    const made = /^new (\w+)\(\)$/.exec(text);
    if (made) {
      if (!names.includes(made[1]) || ['Function', 'BigInt', 'Symbol'].includes(made[1])) return `new ${made[1]}() is not one of the expressions this problem uses.`;
      continue;
    }
    try {
      JSON.parse(text);
    } catch {
      return `${text} is not one of the expressions listed in the statement.`;
    }
  }
  return null;
}

adapter:
function adapt(input, solve, kit) {
  class Animal {}
  class Dog extends Animal {}
  class Cat extends Animal {}
  const named = { Date, Number, String, Boolean, Object, Array, Function, Map, Set, Error, TypeError, BigInt, Symbol, Animal, Dog, Cat };
  // Turns one expression of the statement into the value it describes.
  const build = (text) => {
    if (text === 'undefined') return undefined;
    if (text === 'Symbol()') return Symbol();
    if (text === 'Object.create(null)') return Object.create(null);
    if (text === '() => {}') return () => {};
    if (/^-?\d+n$/.test(text)) return BigInt(text.slice(0, -1));
    if (Object.keys(named).includes(text)) return named[text];
    const made = /^new (\w+)\(\)$/.exec(text);
    if (made) return new named[made[1]]();
    return JSON.parse(text);
  };
  const [obj, classFunction] = input;
  const answer = solve(build(obj), build(classFunction));
  if (typeof answer !== 'boolean') throw new Error('checkIfInstanceOf must return true or false.');
  kit.trace(`checkIfInstanceOf(${obj}, ${classFunction}) returns ${answer}`);
  return answer;
}

