function checkIfInstanceOf(obj, classFunction) {
  if (obj === null || obj === undefined || typeof classFunction !== 'function') return false;
  // instanceof throws when the class has no prototype object, as an arrow function does.
  const target = classFunction.prototype;
  if (target === null || (typeof target !== 'object' && typeof target !== 'function')) return false;
  // Boxing turns a primitive into its wrapper object, which instanceof can test.
  return Object(obj) instanceof classFunction;
}

